#!/usr/bin/env python3
"""
Round 171b (culprits), 4 October 2026. Needs round 170b.

A lighter map for slower computers: a button beside Reload.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 171b (4 October)\n\nNeeds round 170b (guards on its heading). No tiles patch. No app.js?v= bump.\n\n- Asked 4 October: on some computers the map will not all load. A \"Lighter\n  map\" button beside Reload (plain page markup, so it works before the map\n  has loaded) keeps the choice in this browser (localStorage culprits-lite)\n  and reloads at the same view; it then reads \"Full map\" to go back.\n  ?lite=1 or ?lite=0 in the address does the same. index.html notes it as\n  window.__culpritsLite and the class \"lite\" on <html> before app.js runs;\n  app.js asks liteOn().\n- The same layers, basemaps, boxes, keys and filters show. Left out:\n  - the glow round points (hudEligible false: plain dots in each row's own\n    colour, no haze, cores, soft surround or grain);\n  - the density bands under crowded point rows (pointReliefSet never on);\n  - 3D terrain and Raise figures as heights (setTerrain, setLift stay off;\n    the 3D terrain box is hidden);\n  - Combine the ticked layers (comboBox not built);\n  - the Leave Earth button and the zoom-out hand-over to NASA's Eyes (the\n    Eyes layer row still opens it when ticked);\n  - the map draws 1 pixel per screen pixel (was up to 1.5).\n- The WebGL-lost notice on the full map now suggests the lighter map.\n- Tests: the full map has its glow, the lighter one the same layers without\n  it; terrain, raised figures and Combine stay off; the button and the\n  address switch. Browser (SwiftShader): both versions load with no page\n  errors and the button reads right; the map itself never fires \"load\" there.\n- Named 171b because the other chat's basemap round took 170b minutes\n  earlier.\n"]

DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round171b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 170b" not in h.read_text(encoding="utf-8"):
        sys.exit("round171b: round 170b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round171b: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", "map/index.html", check=False)
            sys.exit("round171b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round171b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
